use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// The hosts this node's HTTPClient handle is scoped to. The host enforces the
/// allowlist (an out-of-scope request traps). This copy exists so that a single
/// bad subscription becomes a recorded failure and does not abort the whole tick.
/// It only ever narrows authority. It never widens it.
const ALLOWED_HOSTS: &[&str] = &[
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extract the lowercase host of an http(s) URL, or None if it is malformed.
fn host_of(url: &str) -> Option<String> {
    let lower = url.trim().to_ascii_lowercase();
    let rest = lower
        .strip_prefix("https://")
        .or_else(|| lower.strip_prefix("http://"))?;
    let authority_end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..authority_end];
    // Reject userinfo outright; a feed URL has no business carrying credentials,
    // and "allowed.host@evil.host" style tricks are not worth parsing.
    if authority.contains('@') {
        return None;
    }
    let host = match authority.rfind(':') {
        Some(i) => {
            let port = &authority[i + 1..];
            if port.is_empty() || !port.bytes().all(|b| b.is_ascii_digit()) {
                return None;
            }
            &authority[..i]
        }
        None => authority,
    };
    let host = host.strip_suffix('.').unwrap_or(host);
    if host.is_empty() {
        return None;
    }
    Some(host.to_string())
}

fn is_allowed(url: &str) -> Result<(), String> {
    match host_of(url) {
        None => Err("malformed or unsupported URL".to_string()),
        Some(h) if ALLOWED_HOSTS.iter().any(|a| *a == h) => Ok(()),
        Some(h) => Err(format!("host not in this node's allowlist: {}", h)),
    }
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            if let Err(error) = is_allowed(&url) {
                failures.push(FetchFailure { url, error });
                continue;
            }
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
```

